#include "AutonomousReference.h"
#include "OrientationFixtures.h"
#include <numeric>
namespace autonomous {
using hair::D;using hair::require;
struct Layout{std::vector<int>x,q;unsigned size=0;Layout(const GuideCpuState& cpu,const windowmath::Settings& set){x.resize(cpu.masses.size(),-1);q.resize(cpu.lengths.size(),-1);for(auto r:cpu.ranges)for(unsigned j=0;j<r.vertexCount;j++){if(!(j==0&&set.pinX)){x[r.firstVertex+j]=size;size+=3;}if(j<r.segmentCount&&!(j==0&&set.pinQ)){q[r.firstSegment+j]=size;size+=3;}}}};
D axis(unsigned i){D e;e[int(i)]=1;return e;}
struct System{double energy=0;std::vector<double> gradient,hessian;unsigned n=0;bool jac=false;System(unsigned size,bool derivatives):n(size),jac(derivatives){if(jac){gradient.resize(n);hessian.resize(size_t(n)*n);}}
    void row(double r,const std::vector<std::pair<unsigned,double>>& j){energy+=.5*r*r;if(!jac)return;for(auto [a,ja]:j){gradient[a]+=ja*r;for(auto [b,jb]:j)hessian[size_t(a)*n+b]+=ja*jb;}}
};
System evaluate(const GuideCpuState& cpu,const windowmath::State& state,const std::vector<D>& y,const windowmath::Settings& set,const Layout& layout,bool jac){System system(layout.size,jac);
    for(auto r:cpu.ranges){for(unsigned j=0;j<r.vertexCount;j++){unsigned v=r.firstVertex+j;double weight=std::sqrt(double(cpu.masses[v]))/set.h;D residual=weight*(state.x[v]-y[v]);for(unsigned a=0;a<3;a++){std::vector<std::pair<unsigned,double>> row;if(jac&&layout.x[v]>=0)row.emplace_back(unsigned(layout.x[v])+a,weight);system.row(residual[int(a)],row);}}
    for(unsigned j=0;j<r.segmentCount;j++){unsigned s=r.firstSegment+j,v=r.firstVertex+j;double length=cpu.lengths[s],weight=std::sqrt(double(set.ss)*length);D tangent=hair::rotate(state.q[s],D{0,0,1});D residual=weight*((state.x[v+1]-state.x[v])/length-tangent);
        for(unsigned a=0;a<3;a++){std::vector<std::pair<unsigned,double>> row;if(jac){if(layout.x[v]>=0)row.emplace_back(unsigned(layout.x[v])+a,-weight/length);if(layout.x[v+1]>=0)row.emplace_back(unsigned(layout.x[v+1])+a,weight/length);if(layout.q[s]>=0)for(unsigned b=0;b<3;b++)row.emplace_back(unsigned(layout.q[s])+b,-weight*hair::cross(axis(b),tangent)[int(a)]);}system.row(residual[int(a)],row);}
        if(j+1<r.segmentCount){unsigned next=s+1;D left=state.q[s],right=state.q[next],rest(cpu.bends[r.firstBend+j]),relative=left.conj()*right;D residual=relative-(relative.dot(rest)>=0?1.:-1.)*rest;double w=std::sqrt(4*double(set.bt)/length);for(unsigned a=0;a<4;a++){std::vector<std::pair<unsigned,double>> row;if(jac)for(unsigned b=0;b<3;b++){if(layout.q[s]>=0){D dq=.5*(axis(b)*left);row.emplace_back(unsigned(layout.q[s])+b,w*(dq.conj()*right)[int(a)]);}if(layout.q[next]>=0){D dq=.5*(axis(b)*right);row.emplace_back(unsigned(layout.q[next])+b,w*(left.conj()*dq)[int(a)]);}}system.row(w*residual[int(a)],row);}}
    }}return system;
}
windowmath::State apply(const windowmath::State& state,const Layout& l,const std::vector<double>& step,double scale){auto result=state;for(unsigned v=0;v<l.x.size();v++)if(l.x[v]>=0)for(unsigned k=0;k<3;k++)result.x[v][int(k)]+=scale*step[unsigned(l.x[v])+k];for(unsigned s=0;s<l.q.size();s++)if(l.q[s]>=0){D angle{scale*step[unsigned(l.q[s])],scale*step[unsigned(l.q[s])+1],scale*step[unsigned(l.q[s])+2]};double n=angle.norm();D rotation=n>1e-14?D{angle.x*std::sin(n*.5)/n,angle.y*std::sin(n*.5)/n,angle.z*std::sin(n*.5)/n,std::cos(n*.5)}:D{angle.x*.5,angle.y*.5,angle.z*.5,1}.unit();result.q[s]=(rotation*state.q[s]).unit();}return result;}
ReferenceResult diagnose(const GuideCpuState& cpu,const windowmath::State& s,const windowmath::Settings& set,const Layout& l,const System& sys){ReferenceResult r;r.objective=sys.energy;
    for(auto range:cpu.ranges){for(unsigned j=0;j<range.vertexCount;j++){unsigned v=range.firstVertex+j;if(l.x[v]<0)continue;double diagonal=double(cpu.masses[v])/(double(set.h)*set.h);if(j)diagonal+=double(set.ss)/cpu.lengths[range.firstSegment+j-1];if(j<range.segmentCount)diagonal+=double(set.ss)/cpu.lengths[range.firstSegment+j];D g{sys.gradient[unsigned(l.x[v])],sys.gradient[unsigned(l.x[v])+1],sys.gradient[unsigned(l.x[v])+2]};r.positionCorrection=std::max(r.positionCorrection,g.norm()/diagonal);}
        for(unsigned j=0;j<range.segmentCount;j++){unsigned segment=range.firstSegment+j,v=range.firstVertex+j;if(l.q[segment]<0)continue;D vcoef=(-2*double(set.ss))*(s.x[v+1]-s.x[v]),b,q=s.q[segment];if(j){D rest(cpu.bends[range.firstBend+j-1]),left=s.q[segment-1];b=b+(4*double(set.bt)/cpu.lengths[segment-1]*((left.conj()*q).dot(rest)>=0?1.:-1.))*(left*rest);}if(j+1<range.segmentCount){D rest(cpu.bends[range.firstBend+j]),right=s.q[segment+1];b=b+(4*double(set.bt)/cpu.lengths[segment]*((q.conj()*right).dot(rest)>=0?1.:-1.))*(right*rest.conj());}double violation=0,scale=vcoef.norm()+b.norm(),res=hair::residual(vcoef,b,q,violation);if(scale){r.stationarity=std::max(r.stationarity,res/scale);r.spectral=std::max(r.spectral,violation/scale);}}}return r;
}
ReferenceResult minimize(const GuideCpuState& cpu,windowmath::State& state,const std::vector<D>& y,const windowmath::Settings& set,double ptol,double qtol){Layout layout(cpu,set);for(unsigned s=0;s<layout.q.size();s++)if(layout.q[s]>=0)state.q[s]=state.q[s].unit();double lambda=1e-8;ReferenceResult result;
    for(unsigned iteration=0;iteration<1500;iteration++){auto system=evaluate(cpu,state,y,set,layout,true);result=diagnose(cpu,state,set,layout,system);result.iterations=iteration;require(std::isfinite(result.objective),"Double reference nonfinite objective");if(result.positionCorrection<ptol&&result.stationarity<qtol&&result.spectral<qtol){result.qualified=true;return result;}
        unsigned n=layout.size;constexpr unsigned band=12;bool accepted=false;
        for(unsigned retry=0;retry<16;retry++){std::vector<double> a(size_t(n)*n),rhs(n),scale(n),step(n);for(unsigned i=0;i<n;i++){scale[i]=std::sqrt(std::max(system.hessian[size_t(i)*n+i],1e-30));rhs[i]=-system.gradient[i]/scale[i];}
            for(unsigned i=0;i<n;i++)for(unsigned j=i>band?i-band:0;j<=i;j++){double value=system.hessian[size_t(i)*n+j]/(scale[i]*scale[j])+(i==j?lambda:0);for(unsigned k=std::max(i>band?i-band:0,j>band?j-band:0);k<j;k++)value-=a[size_t(i)*n+k]*a[size_t(j)*n+k];if(i==j){require(value>0&&std::isfinite(value),"Reference Cholesky pivot failure");a[size_t(i)*n+i]=std::sqrt(value);}else a[size_t(i)*n+j]=value/a[size_t(j)*n+j];}
            for(unsigned i=0;i<n;i++){for(unsigned j=i>band?i-band:0;j<i;j++)rhs[i]-=a[size_t(i)*n+j]*rhs[j];rhs[i]/=a[size_t(i)*n+i];}
            for(unsigned i=n;i-->0;){double value=rhs[i];for(unsigned j=i+1;j<std::min(n,i+band+1);j++)value-=a[size_t(j)*n+i]*step[j];step[i]=value/a[size_t(i)*n+i];}
            for(unsigned i=0;i<n;i++)step[i]/=scale[i];
            for(unsigned line=0;line<16;line++){auto candidate=apply(state,layout,step,std::ldexp(1.,-int(line)));double e=evaluate(cpu,candidate,y,set,layout,false).energy;if(std::isfinite(e)&&e<system.energy){state=std::move(candidate);accepted=true;break;}}
            if(accepted){lambda=std::max(1e-12,lambda*.2);break;}lambda=std::min(1e12,lambda*10);
        }if(!accepted)return result;
    }return result;
}
double derivativeTest(const GuideCpuState& cpu,const windowmath::Settings& set){auto state=windowmath::rest(cpu);Layout l(cpu,set);std::vector<D> y=state.x;for(unsigned v=0;v<l.x.size();v++)if(l.x[v]>=0){double u=(v%31)/31.;state.x[v]=state.x[v]+D{.0003*std::sin(u),-.0002*u,.0001*u*u};}for(unsigned s=0;s<l.q.size();s++)if(l.q[s]>=0)state.q[s]=(hair::axisAngle(D{1,.3,.7},.1*std::sin(s+.5))*state.q[s]).unit();auto system=evaluate(cpu,state,y,set,l,true);double error=0;for(unsigned i=0;i<l.size;i+=std::max(1u,l.size/40)){std::vector<double> d(l.size);d[i]=1;double h=l.x.size()>0?1e-6:1e-6;auto a=apply(state,l,d,h),b=apply(state,l,d,-h);double fd=(evaluate(cpu,a,y,set,l,false).energy-evaluate(cpu,b,y,set,l,false).energy)/(2*h);error=std::max(error,std::abs(fd-system.gradient[i])/std::max(1.,std::abs(fd)));}require(error<2e-8,"Independent reference analytic Jacobian finite difference failed");return error;}
}
